steps.action_code:
supervisor_profile = apis.supervisor.show_profile()
account_password_records = apis.supervisor.show_account_passwords()

def _normalize_account_name(_value):
    return "".join(_character for _character in str(_value).lower() if _character.isalnum())

def _password_for_app(_app_name):
    _target = _normalize_account_name(_app_name)
    _matches = [
        _record for _record in account_password_records
        if _target == _normalize_account_name(_record["account_name"])
        or _target in _normalize_account_name(_record["account_name"])
        or _normalize_account_name(_record["account_name"]) in _target
    ]
    if len(_matches) != 1:
        raise RuntimeError("Could not uniquely resolve credentials for " + _app_name)
    return _matches[0]["password"]

phone_password = _password_for_app("phone")
file_system_password = _password_for_app("file_system")
venmo_password = _password_for_app("venmo")
print({
    "first_name": supervisor_profile["first_name"],
    "last_name": supervisor_profile["last_name"],
    "email": supervisor_profile["email"],
    "phone_number": supervisor_profile["phone_number"],
})

from datetime import datetime as _DateTime
import re as _re

_raw_date = str(current_date_and_time.get("date", "")).strip()
_date_variants = [_raw_date]
if "," in _raw_date:
    _date_variants.append(_raw_date.split(",", 1)[1].strip())
_date_variants += [
    _re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", _variant, flags=_re.IGNORECASE)
    for _variant in list(_date_variants)
]
_current_calendar_date = None
for _variant in _date_variants:
    try:
        _current_calendar_date = _DateTime.fromisoformat(_variant.replace("Z", "+00:00"))
        break
    except ValueError:
        pass
    for _format in (
        "%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y",
        "%m-%d-%Y", "%d-%m-%Y", "%B %d, %Y", "%b %d, %Y",
        "%B %d %Y", "%b %d %Y", "%d %B, %Y", "%d %b, %Y",
        "%d %B %Y", "%d %b %Y",
    ):
        try:
            _current_calendar_date = _DateTime.strptime(_variant, _format)
            break
        except ValueError:
            pass
    if _current_calendar_date is not None:
        break
if _current_calendar_date is None:
    raise RuntimeError("The phone date could not be parsed using supported public date formats")
if _current_calendar_date.month == 1:
    target_bill_year = _current_calendar_date.year - 1
    target_bill_month = 12
else:
    target_bill_year = _current_calendar_date.year
    target_bill_month = _current_calendar_date.month - 1
target_bill_period = f"{target_bill_year:04d}-{target_bill_month:02d}"
print({"target_billing_month": target_bill_period})

receipt_file_records = []
for _file_path in electricity_file_paths:
    receipt_file_records.append(
        apis.file_system.show_file(
            file_path=_file_path,
            access_token=file_system_access_token,
        )
    )
print([
    {
        "path": _record["path"],
        "content": _record["content"],
        "created_at": _record["created_at"],
        "updated_at": _record["updated_at"],
    }
    for _record in receipt_file_records
])

from decimal import Decimal as _Decimal

if not receipt_file_records:
    raise RuntimeError("No electricity receipt candidate was found")
_month_names = (
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
)
_target_month_name = _month_names[target_bill_month - 1]
_target_month_abbreviation = _target_month_name[:3]
_target_year_text = str(target_bill_year)
_numeric_period_tokens = (
    f"{target_bill_year:04d}-{target_bill_month:02d}",
    f"{target_bill_year:04d}_{target_bill_month:02d}",
    f"{target_bill_year:04d}/{target_bill_month:02d}",
    f"{target_bill_month:02d}-{target_bill_year:04d}",
    f"{target_bill_month:02d}_{target_bill_year:04d}",
    f"{target_bill_month:02d}/{target_bill_year:04d}",
)

def _receipt_period_score(_record):
    _searchable = (str(_record["path"]) + "\n" + str(_record["content"])).lower()
    _score = 0
    if _target_year_text in _searchable and _re.search(r"\b" + _re.escape(_target_month_name) + r"\b", _searchable):
        _score += 6
    if _target_year_text in _searchable and _re.search(r"\b" + _re.escape(_target_month_abbreviation) + r"\b", _searchable):
        _score += 4
    _score += sum(3 for _token in _numeric_period_tokens if _token in _searchable)
    return _score

_scored_receipts = [(_receipt_period_score(_record), _record) for _record in receipt_file_records]
if len(_scored_receipts) == 1:
    selected_receipt = _scored_receipts[0][1]
else:
    _best_score = max(_score for _score, _record in _scored_receipts)
    _best_receipts = [_record for _score, _record in _scored_receipts if _score == _best_score]
    if _best_score <= 0 or len(_best_receipts) != 1:
        raise RuntimeError("The prior-month electricity receipt could not be selected uniquely")
    selected_receipt = _best_receipts[0]

_receipt_content = str(selected_receipt["content"])
_amount_patterns = (
    r"(?i)\b(?:amount\s+paid|payment\s+amount|total\s+paid|bill\s+total|grand\s+total|total\s+amount|amount\s+due|total\s+due)\b\s*[:=\-]?\s*(?:USD\s*)?\$?\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)",
    r"(?i)\b(?:total|paid|amount)\b\s*[:=\-]?\s*(?:USD\s*)?\$?\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)",
)
bill_amount = None
for _pattern in _amount_patterns:
    _values = {
        _Decimal(_match.replace(",", ""))
        for _match in _re.findall(_pattern, _receipt_content)
    }
    _positive_values = {_value for _value in _values if _value > 0}
    if len(_positive_values) == 1:
        bill_amount = next(iter(_positive_values))
        break
    if len(_positive_values) > 1:
        raise RuntimeError("The receipt contains multiple competing labeled totals")
if bill_amount is None:
    _currency_values = {
        _Decimal(_match.replace(",", ""))
        for _match in _re.findall(r"(?i)(?:USD\s*|\$\s*)([0-9][0-9,]*(?:\.[0-9]{1,2})?)", _receipt_content)
    }
    _currency_values = {_value for _value in _currency_values if _value > 0}
    if len(_currency_values) != 1:
        raise RuntimeError("A unique positive receipt amount could not be extracted")
    bill_amount = next(iter(_currency_values))
print({"selected_receipt_path": selected_receipt["path"], "bill_amount": str(bill_amount)})

from decimal import ROUND_HALF_UP as _ROUND_HALF_UP

if not roommate_contacts:
    raise RuntimeError("No roommate contacts were found")
if any(not str(_contact.get("email", "")).strip() for _contact in roommate_contacts):
    raise RuntimeError("A roommate contact lacks the email required by Venmo")
_self_email = str(supervisor_profile["email"]).strip().lower()
roommate_emails = sorted({
    str(_contact["email"]).strip().lower()
    for _contact in roommate_contacts
    if str(_contact["email"]).strip().lower() != _self_email
})
if not roommate_emails:
    raise RuntimeError("No distinct roommate recipient emails remain after review")
participant_count = len(roommate_emails) + 1
per_person_share = (bill_amount / _Decimal(participant_count)).quantize(
    _Decimal("0.01"),
    rounding=_ROUND_HALF_UP,
)
if per_person_share <= 0:
    raise RuntimeError("The computed roommate share is not positive")
planned_requests = [
    {
        "user_email": _email,
        "amount": float(per_person_share),
        "description": "For electricity bill.",
    }
    for _email in roommate_emails
]
print({
    "bill_amount": str(bill_amount),
    "participant_count_including_payer": participant_count,
    "requests": planned_requests,
})

payment_request_results = []
for _planned_request in planned_requests:
    _response = apis.venmo.create_payment_request(
        user_email=_planned_request["user_email"],
        amount=_planned_request["amount"],
        access_token=venmo_access_token,
        description=_planned_request["description"],
    )
    payment_request_results.append({
        "request": _planned_request,
        "response": _response,
    })
print([
    {
        "user_email": _result["request"]["user_email"],
        "payment_request_id": _result["response"]["payment_request_id"],
    }
    for _result in payment_request_results
])

if len(payment_request_results) != len(planned_requests):
    raise RuntimeError("The number of mutation results does not match the reviewed request batch")
_verified_request_ids = []
for _result in payment_request_results:
    _request_id = _result["response"].get("payment_request_id")
    if not isinstance(_request_id, int):
        raise RuntimeError("A Venmo mutation did not return a payment_request_id")
    if _result["request"]["description"] != "For electricity bill.":
        raise RuntimeError("A submitted request did not use the required description")
    if _result["request"]["amount"] != float(per_person_share):
        raise RuntimeError("A submitted request did not use the reviewed equal share")
    _verified_request_ids.append(_request_id)
if len(set(_verified_request_ids)) != len(_verified_request_ids):
    raise RuntimeError("Venmo returned duplicate payment-request identifiers")
verification_summary = {
    "planned_roommate_requests": len(planned_requests),
    "acknowledged_roommate_requests": len(_verified_request_ids),
    "payment_request_ids": _verified_request_ids,
    "amount_each": float(per_person_share),
    "description": "For electricity bill.",
}
print(verification_summary)
